const manifest = {
  contracts: { additiveClean: true },
  gold: { api: '12/12', ui: '9/10' },
  budgets: { p99margin: 25 },
  guardrails: { attackGold: '9/9' },
  ops: { runbooksPracticed: true },
  residual: [{ risk: 'novel attacks', owner: 'security', date: '2027-02-01' }],
};
const checks = [
  ['contracts additive', manifest.contracts.additiveClean === true],
  ['api gold full', manifest.gold.api === '12/12'],
  ['ui gold noted-weak', manifest.gold.ui === '9/10'],
  ['budget headroom', manifest.budgets.p99margin > 0],
  ['guards proven', manifest.guardrails.attackGold === '9/9'],
  ['residuals owned', manifest.residual.every((r) => r.owner && r.date)],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'conditional approval' : 'BLOCKED');

